import{recordUsage}from"#harness/usage-sink.js";import{extractGatewayCostUsd}from"#harness/model-call/usage.js";import{decideWithTracing}from"#instrumentation/decide.js";function decide(e){return decideFor(`custom`,e)}async function decideFor(e,t){let n=await decideWithTracing(t,e);return await recordUsage({costUsd:extractGatewayCostUsd(n.providerMetadata),inputTokens:n.usage.inputTokens,outputTokens:n.usage.outputTokens},{kind:`decision`}),{answers:n.answers,usage:{inputTokens:n.usage.inputTokens,outputTokens:n.usage.outputTokens,totalTokens:n.usage.totalTokens}}}export{decide,decideFor};