function decisionResults(e,t){return Object.entries(e).flatMap(([e,n],r)=>{let i={question_index:r,question_name:e};if(`refused`in t)return t.refused.includes(e)?[{...i,type:`refusal`}]:[];let a=t.answers[e];if(a?.type===`refusal`)return[{...i,type:`refusal`}];if(a?.type!==n.type)return[];if(n.type===`boolean`&&typeof a.probability==`number`)return[{...i,type:`predicate`,probability:a.probability}];if(n.type===`choice`&&typeof a.choice==`string`){let e={...i,type:`choice`,value:a.choice};let t=a.probabilities?.[a.choice];return typeof t==`number`&&(e.probability=t),[e]}if(n.type===`score`&&typeof a.score==`number`){let e=n.criteria;return e.length<2||!e.every(e=>typeof e==`string`)?[]:[{...i,type:`score`,value:a.score,levels:[...e]}]}return[]})}export{decisionResults};